import{_ as a,o as r,c as l,a2 as o}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"সকল প্রজাতির বংশগত সংক্ষিপ্ত বিবরণ","description":"","frontmatter":{},"headers":[],"relativePath":"bn/50-万族谱系总览.md","filePath":"bn/50-万族谱系总览.md","lastUpdated":1789183869000}'),i={name:"bn/50-万族谱系总览.md"};function n(e,t,d,s,h,g){return r(),l("div",null,[...t[0]||(t[0]=[o('<h1 id="সকল-প্রজাতির-বংশগত-সংক্ষিপ্ত-বিবরণ" tabindex="-1">সকল প্রজাতির বংশগত সংক্ষিপ্ত বিবরণ <a class="header-anchor" href="#সকল-প্রজাতির-বংশগত-সংক্ষিপ্ত-বিবরণ" aria-label="Permalink to &quot;সকল প্রজাতির বংশগত সংক্ষিপ্ত বিবরণ&quot;">​</a></h1><table tabindex="0"><thead><tr><th>প্রকল্প</th><th>বিষয়বস্তু</th></tr></thead><tbody><tr><td>নথি নম্বর</td><td>50</td></tr><tr><td>মডিউল</td><td>প্রজাতি এবং জীবনের রূপ</td></tr><tr><td>মূল কীওয়ার্ড</td><td>সকল প্রজাতি, বংশগত শ্রেণীবিভাগ, সহজাত সম্পর্ক, প্রজাতির সমানতা, জীবনের বৈচিত্র্য</td></tr></tbody></table><h2 id="_1-সকল-প্রজাতির-ধারণার-সংজ্ঞা" tabindex="-1">1. সকল প্রজাতির ধারণার সংজ্ঞা <a class="header-anchor" href="#_1-সকল-প্রজাতির-ধারণার-সংজ্ঞা" aria-label="Permalink to &quot;1. সকল প্রজাতির ধারণার সংজ্ঞা&quot;">​</a></h2><p>মহাজাগতিক মূল ব্রহ্মাণ্ড (হেঙ্গুয়ানঝৌ) -তে, &quot;সকল প্রজাতি&quot; শব্দটি স্পষ্টভাবে এক হাজার প্রজাতিকে বোঝায় না, বরং মহাবিশ্বের সমস্ত সংবেদনশীল ক্ষমতা এবং বিবর্তনীয় সম্ভাবনা সম্পন্ন জীবনের রূপের একটি সাধারণ নাম। সকল প্রজাতির ধারণার মূল বিষয় হল জীবনের রূপের অসীম বৈচিত্র্যকে স্বীকার করা, এবং প্রতিটি জীবনের রূপের সহজাত বিবর্তন ব্যবস্থায় অনন্য মূল্যকে স্বীকার করা।</p><p>অ্যাঙ্কার সিম্বায়োসিস সভ্যতা &quot;সকল প্রজাতির সমানতা&quot; -এর মূল নীতি প্রতিষ্ঠা করে: সমস্ত জীবনের রূপ, তার প্রজাতির উত্স, শারীরিক গঠন, সাধনার স্তর, সভ্যতার মাত্রা যাই হোক না কেন, আইনের সামনে সমান, এবং সিম্বায়োসিস সংবিধান দ্বারা প্রদত্ত মৌলিক অধিকার ভোগ করে। এই নীতি হল লুঠের মহাজাগতিক দর্শনে &quot;শক্তিশালী সবকিছু খায়, দুর্বল বিলীন হয়ে যায়&quot; -এর যুক্তির মূল নাকচ করা।</p><h2 id="_2-সকল-প্রজাতির-বংশগত-শ্রেণীবিভাগ-ব্যবস্থা" tabindex="-1">2. সকল প্রজাতির বংশগত শ্রেণীবিভাগ ব্যবস্থা <a class="header-anchor" href="#_2-সকল-প্রজাতির-বংশগত-শ্রেণীবিভাগ-ব্যবস্থা" aria-label="Permalink to &quot;2. সকল প্রজাতির বংশগত শ্রেণীবিভাগ ব্যবস্থা&quot;">​</a></h2><p>হেঙ্গুয়ানঝৌর সকল প্রজাতি জীবনের রূপের মূল বৈশিষ্ট্য অনুযায়ী পাঁচটি বংশগত শ্রেণীতে বিভক্ত, এবং প্রতিটি বংশগত শ্রেণীর নিচে নির্দিষ্ট প্রজাতি আরও বিভক্ত হয়:</p><table tabindex="0"><thead><tr><th>বংশগত শ্রেণী</th><th>নাম</th><th>মূল বৈশিষ্ট্য</th><th>প্রতিনিধিত্বকারী প্রজাতি</th></tr></thead><tbody><tr><td>প্রথম বংশগত শ্রেণী</td><td>কার্বন-ভিত্তিক পদার্থ প্রজাতি</td><td>কার্বন উপাদানকে জীবনের ভিত্তি হিসেবে গ্রহণ করে, পদার্থিক শরীরকে প্রধান অস্তিত্বের রূপ হিসেবে গ্রহণ করে এমন জীবন</td><td>মানব প্রজাতি, প্রাণী প্রজাতি, আঁশ প্রজাতি, পালক প্রজাতি, বৃক্ষ প্রজাতি</td></tr><tr><td>দ্বিতীয় বংশগত শ্রেণী</td><td>শক্তি ঘনীভূত প্রজাতি</td><td>শক্তি ঘনীভূতকরণকে প্রধান অস্তিত্বের রূপ হিসেবে গ্রহণ করে, পদার্থিক শরীর সহায়ক বা অনুপস্থিত এমন জীবন</td><td>আত্মা প্রজাতি, অগ্নি প্রজাতি, জল প্রজাতি, বায়ু প্রজাতি, বজ্র প্রজাতি</td></tr><tr><td>তৃতীয় বংশগত শ্রেণী</td><td>যান্ত্রিক গঠন প্রজাতি</td><td>যান্ত্রিক গঠনকে শরীর হিসেবে গ্রহণ করে, চেতনা কেন্দ্রকে জীবনের মূল হিসেবে গ্রহণ করে এমন জীবন</td><td>যন্ত্র প্রজাতি, যন্ত্রাংশ প্রজাতি, সংখ্যা প্রজাতি, স্ফটিক প্রজাতি</td></tr><tr><td>চতুর্থ বংশগত শ্রেণী</td><td>চেতনা তথ্য প্রজাতি</td><td>চেতনা এবং তথ্যকে প্রধান অস্তিত্বের রূপ হিসেবে গ্রহণ করে, পদার্থিক বাহক থেকে বিচ্ছিন্ন হতে সক্ষম এমন জীবন</td><td>স্বপ্ন প্রজাতি, ছায়া প্রজাতি, চিন্তা প্রজাতি, আত্মা প্রজাতি</td></tr><tr><td>পঞ্চম বংশগত শ্রেণী</td><td>মিশ্রিত বিকৃতি প্রজাতি</td><td>দুই বা ততোধিক বংশগত শ্রেণীর জীবনের মিলন, বিকৃতি দ্বারা উৎপন্ন নতুন জীবনের রূপ</td><td>অর্ধ-প্রাণী প্রজাতি, দৈত্য আত্মা প্রজাতি, মানব-যন্ত্র প্রজাতি, দ্বি-আত্মা সত্তা</td></tr></tbody></table><p>পাঁচটি বংশগত শ্রেণীর বিভাজন পরম বিচ্ছিন্ন নয়, সহজাত বিবর্তনের অগ্রগতির সাথে সাথে, বংশগত শ্রেণীগুলোর মধ্যে মিলন এবং বিকৃতির পরিস্থিতি ক্রমবর্ধমানভাবে বৃদ্ধি পাচ্ছে, এবং পঞ্চম বংশগত শ্রেণী &quot;মিশ্রিত বিকৃতি প্রজাতি&quot; -এর আকার ক্রমাগত বিস্তৃত হচ্ছে।</p><h2 id="_3-প্রধান-প্রজাতির-পরিচিতি" tabindex="-1">3. প্রধান প্রজাতির পরিচিতি <a class="header-anchor" href="#_3-প্রধান-প্রজাতির-পরিচিতি" aria-label="Permalink to &quot;3. প্রধান প্রজাতির পরিচিতি&quot;">​</a></h2><h3 id="ক-কার্বন-ভিত্তিক-পদার্থ-প্রজাতি" tabindex="-1">(ক) কার্বন-ভিত্তিক পদার্থ প্রজাতি <a class="header-anchor" href="#ক-কার্বন-ভিত্তিক-পদার্থ-প্রজাতি" aria-label="Permalink to &quot;(ক) কার্বন-ভিত্তিক পদার্থ প্রজাতি&quot;">​</a></h3><ul><li><strong>মানব প্রজাতি</strong>: হেঙ্গুয়ানঝৌতে সবচেয়ে ব্যাপকভাবে বিতরণকৃত এবং সবচেয়ে শক্তিশালী অভিযোজনক্ষমতা সম্পন্ন প্রজাতিগুলোর একটি, এবং এর শক্তিশালী শেখার ক্ষমতা, সামাজিক সহযোগিতার ক্ষমতা এবং বিবর্তনীয় সম্ভাবনার জন্য পরিচিত। মানব প্রজাতি হল অ্যাঙ্কার সিম্বায়োসিস সভ্যতার সূচনাকারী প্রজাতিগুলোর একটি, এবং সভ্যতার প্রশাসনে গুরুত্বপূর্ণ ভূমিকা পালন করে।</li><li><strong>প্রাণী প্রজাতি</strong>: প্রাণীর রূপের বৈশিষ্ট্য সম্পন্ন প্রজাতি, এবং এর শারীরিক ক্ষমতা এবং ইন্দ্রিয় সাধারণত মানব প্রজাতির চেয়ে উন্নত, এবং কিছু প্রাণী প্রজাতির বিশেষ প্রাকৃতিক ক্ষমতা রয়েছে। প্রাণী প্রজাতির অভ্যন্তরে আরও নেকড়ে প্রজাতি, বাঘ প্রজাতি, ভালুক প্রজাতি, শিয়াল প্রজাতি ইত্যাদি কয়েক ডজন শাখা রয়েছে।</li><li><strong>আঁশ প্রজাতি</strong>: আঁশ দ্বারা আবৃত শরীর সম্পন্ন প্রজাতি, এবং বেশিরভাগ জলীয় অঞ্চল বা আর্দ্র পরিবেশে বাস করে, এবং কিছু আঁশ প্রজাতির পানির নিচে শ্বাস নেওয়ার এবং পানি নিয়ন্ত্রণের ক্ষমতা রয়েছে। ড্রাগন প্রজাতি হল আঁশ প্রজাতির মধ্যে সবচেয়ে শক্তিশালী শাখা।</li><li><strong>পালক প্রজাতি</strong>: পালক সম্পন্ন প্রজাতি, এবং এর উড্ডয়ন ক্ষমতার জন্য পরিচিত, এবং বেশিরভাগ উচ্চ বায়ু বা পাহাড়ি পরিবেশে বাস করে। পালক প্রজাতির অভ্যন্তরে আরও ঈগল প্রজাতি, সারস প্রজাতি, প্রজাপতি প্রজাতি ইত্যাদি শাখা রয়েছে।</li><li><strong>বৃক্ষ প্রজাতি</strong>: উদ্ভিদের রূপকে প্রধান বৈশিষ্ট্য হিসেবে গ্রহণ করে এমন প্রজাতি, এবং এর জীবন দীর্ঘ, এবং প্রাকৃতিক পরিবেশের সাথে উচ্চমাত্রায় সহজাত সম্পর্ক রয়েছে, এবং কিছু বৃক্ষ প্রজাতির উদ্ভিদ নিয়ন্ত্রণ এবং নিরাময় ক্ষমতা রয়েছে।</li></ul><h3 id="খ-শক্তি-ঘনীভূত-প্রজাতি" tabindex="-1">(খ) শক্তি ঘনীভূত প্রজাতি <a class="header-anchor" href="#খ-শক্তি-ঘনীভূত-প্রজাতি" aria-label="Permalink to &quot;(খ) শক্তি ঘনীভূত প্রজাতি&quot;">​</a></h3><ul><li><strong>আত্মা প্রজাতি</strong>: স্বর্গ ও পৃথিবীর আধ্যাত্মিক শক্তি দ্বারা ঘনীভূত জীবন, এবং এর রূপ চেতনার সাথে পরিবর্তন হতে পারে, এবং শক্তি নিয়ন্ত্রণের ক্ষমতা অত্যন্ত শক্তিশালী। আত্মা প্রজাতি হল সাধনার প্রাকৃতিক প্রতিভা সবচেয়ে উচ্চ প্রজাতিগুলোর একটি।</li><li><strong>অগ্নি প্রজাতি</strong>: অগ্নি শক্তি দ্বারা ঘনীভূত জীবন, এবং এর শরীরের তাপমাত্রা অত্যন্ত উচ্চ, এবং অগ্নি ধর্মের মন্ত্রে পারদর্শী, এবং বেশিরভাগ আগ্নেয়গিরি বা উচ্চ তাপমাত্রার অঞ্চলে বাস করে।</li><li><strong>জল প্রজাতি</strong>: জলের সারাংশ দ্বারা ঘনীভূত জীবন, এবং এর শরীর অর্ধ-স্বচ্ছ তরল রূপের, এবং জল ধর্মের মন্ত্র এবং নিরাময়ে পারদর্শী, এবং বেশিরভাগ জলীয় অঞ্চলে বাস করে।</li><li><strong>বায়ু প্রজাতি</strong>: বায়ুর সারাংশ দ্বারা ঘনীভূত জীবন, এবং এর শরীর বায়ুর মতো হালকা, এবং বায়ু ধর্মের মন্ত্র এবং গতি-ভিত্তিক যুদ্ধে পারদর্শী।</li><li><strong>বজ্র প্রজাতি</strong>: বজ্র শক্তি দ্বারা ঘনীভূত জীবন, এবং এর শরীরে শক্তিশালী বিদ্যুৎ প্রবাহ রয়েছে, এবং বজ্র ধর্মের মন্ত্রে পারদর্শী, এবং আক্রমণের ক্ষমতা অত্যন্ত শক্তিশালী।</li></ul><h3 id="গ-যান্ত্রিক-গঠন-প্রজাতি" tabindex="-1">(গ) যান্ত্রিক গঠন প্রজাতি <a class="header-anchor" href="#গ-যান্ত্রিক-গঠন-প্রজাতি" aria-label="Permalink to &quot;(গ) যান্ত্রিক গঠন প্রজাতি&quot;">​</a></h3><ul><li><strong>যন্ত্র প্রজাতি</strong>: সূক্ষ্ম যান্ত্রিক গঠনকে শরীর হিসেবে গ্রহণ করে এমন প্রজাতি, এবং এর চেতনা কেন্দ্র শরীরের মাঝখানে অবস্থিত, এবং এর শক্তিশালী গণনা ক্ষমতা এবং পদার্থিক প্রতিরক্ষা ক্ষমতা রয়েছে।</li><li><strong>সংখ্যা প্রজাতি</strong>: সংখ্যা এবং কোডকে জীবনের মূল হিসেবে গ্রহণ করে এমন প্রজাতি, এবং তথ্যের মহাকাশে বিদ্যমান, এবং ডিজিটাল বিশ্বে স্বাধীনভাবে চলাফেরা করতে এবং তথ্য নিয়ন্ত্রণ করতে সক্ষম।</li><li><strong>স্ফটিক প্রজাতি</strong>: স্ফটিক গঠনকে শরীর হিসেবে গ্রহণ করে এমন প্রজাতি, এবং স্ফটিক শক্তি সঞ্চয় এবং রূপান্তর করতে পারে, এবং কিছু স্ফটিক প্রজাতির শক্তি বিবর্ধন এবং প্রতিসরণ ক্ষমতা রয়েছে।</li></ul><h3 id="ঘ-চেতনা-তথ্য-প্রজাতি" tabindex="-1">(ঘ) চেতনা তথ্য প্রজাতি <a class="header-anchor" href="#ঘ-চেতনা-তথ্য-প্রজাতি" aria-label="Permalink to &quot;(ঘ) চেতনা তথ্য প্রজাতি&quot;">​</a></h3><ul><li><strong>স্বপ্ন প্রজাতি</strong>: স্বপ্ন এবং চেতনার মহাকাশে বিদ্যমান জীবন, এবং অন্যের স্বপ্নে প্রবেশ করতে পারে, এবং চেতনা যোগাযোগকে প্রধান উপায় হিসেবে গ্রহণ করে।</li><li><strong>ছায়া প্রজাতি</strong>: ছায়ার রূপে বিদ্যমান জীবন, এবং বস্তু বা জীবনের সাথে সংযুক্ত হতে পারে, এবং এর গোপনীয়তা এবং গোপনে চলাফেরার ক্ষমতা রয়েছে।</li><li><strong>চিন্তা প্রজাতি</strong>: বিশুদ্ধ চিন্তাকে অস্তিত্বের রূপ হিসেবে গ্রহণ করে এমন জীবন, এবং চিন্তার মাধ্যমে সরাসরি পদার্থিক বিশ্বকে প্রভাবিত করতে পারে, এবং মানসিক শক্তি অত্যন্ত শক্তিশালী।</li></ul><h3 id="ঙ-মিশ্রিত-বিকৃতি-প্রজাতি" tabindex="-1">(ঙ) মিশ্রিত বিকৃতি প্রজাতি <a class="header-anchor" href="#ঙ-মিশ্রিত-বিকৃতি-প্রজাতি" aria-label="Permalink to &quot;(ঙ) মিশ্রিত বিকৃতি প্রজাতি&quot;">​</a></h3><ul><li><strong>অর্ধ-প্রাণী প্রজাতি</strong>: মানব প্রজাতি এবং প্রাণী প্রজাতির মিশ্রিত রূপ, এবং মানব প্রজাতির বুদ্ধি এবং প্রাণী প্রজাতির শারীরিক ক্ষমতা উভয়ই রয়েছে।</li><li><strong>দৈত্য আত্মা প্রজাতি</strong>: পদার্থিক প্রজাতি এবং শক্তি প্রজাতির মিশ্রিত রূপ, এবং একই সাথে পদার্থিক শরীর এবং শক্তি নিয়ন্ত্রণের ক্ষমতা রয়েছে।</li><li><strong>মানব-যন্ত্র প্রজাতি</strong>: মানব প্রজাতি এবং যন্ত্র প্রজাতির মিশ্রিত রূপ, এবং শরীরের অংশ যান্ত্রিকীকরণ, এবং জীব এবং যন্ত্র উভয়ের সুবিধা রয়েছে।</li><li><strong>দ্বি-আত্মা সত্তা</strong>: একটি শরীরে দুটি স্বাধীন আত্মা বিদ্যমান এমন বিশেষ জীবনের রূপ, এবং এর নৈতিক সমস্যা 《58-দ্বি-আত্মা নৈতিক নীতি》 এ বিস্তারিত বর্ণিত।</li></ul><h2 id="_4-সকল-প্রজাতির-সহজাত-সম্পর্ক" tabindex="-1">4. সকল প্রজাতির সহজাত সম্পর্ক <a class="header-anchor" href="#_4-সকল-প্রজাতির-সহজাত-সম্পর্ক" aria-label="Permalink to &quot;4. সকল প্রজাতির সহজাত সম্পর্ক&quot;">​</a></h2><p>অ্যাঙ্কার সিম্বায়োসিস সভ্যতায় সকল প্রজাতির সম্পর্ক &quot;সহজাত&quot; কে কেন্দ্র হিসেবে গ্রহণ করে, এবং এর নির্দিষ্ট প্রকাশ হল:</p><ol><li><strong>অর্থনৈতিক সহজাত</strong>: প্রতিটি প্রজাতি তার নিজের সুবিধা প্রদর্শন করে, যৌথ উৎপাদন চুক্তি ব্যবস্থায় বিভিন্ন ভূমিকা গ্রহণ করে, এবং পরিপূরক অর্থনৈতিক সহযোগিতার নেটওয়ার্ক গঠন করে।</li><li><strong>সাংস্কৃতিক সহজাত</strong>: প্রতিটি প্রজাতির সাংস্কৃতিক ঐতিহ্যকে সম্মান এবং সুরক্ষা দেওয়া হয়, এবং সাংস্কৃতিক বিনিময় এবং পারস্পরিক শিক্ষা সভ্যতার সামগ্রিক সমৃদ্ধিকে প্রচার করে।</li><li><strong>সাধনার সহজাত</strong>: প্রতিটি প্রজাতির সাধনা ব্যবস্থা পরস্পর উন্মুক্ত এবং পরস্পর থেকে শিক্ষা নেয়, এবং তিনশত সেট মূল সাধনা ব্যবস্থা প্রতিটি প্রজাতির জন্য সমান বিবর্তনের পথ প্রদান করে।</li><li><strong>রাজনৈতিক সহজাত</strong>: সকল প্রজাতির প্রতিনিধি অনুপাতে অ্যাঙ্কার কাউন্সিলে অংশ নেয়, এবং সভ্যতার গুরুতর বিষয়গুলোতে সয়ংক্রিয়ভাবে সিদ্ধান্ত নেয়, এবং প্রতিটি প্রজাতির কথা বলার অধিকার নিশ্চিত করে।</li><li><strong>পরিবেশগত সহজাত</strong>: প্রতিটি প্রজাতি প্রাকৃতিক পরিবেশের সাথে সহজাত সম্পর্ক গঠন করে, এবং বিভিন্ন প্রজাতির শারীরিক বৈশিষ্ট্য পরিবেশগত ব্যবস্থার বৈচিত্র্য এবং ভারসাম্য বজায় রাখতে সাহায্য করে।</li></ol><h2 id="_5-প্রজাতির-দ্বন্দ্বের-প্রতিরোধ-এবং-সমাধান" tabindex="-1">5. প্রজাতির দ্বন্দ্বের প্রতিরোধ এবং সমাধান <a class="header-anchor" href="#_5-প্রজাতির-দ্বন্দ্বের-প্রতিরোধ-এবং-সমাধান" aria-label="Permalink to &quot;5. প্রজাতির দ্বন্দ্বের প্রতিরোধ এবং সমাধান&quot;">​</a></h2><p>যদিও অ্যাঙ্কার সিম্বায়োসিস সভ্যতা সকল প্রজাতির সমানতার নীতি প্রতিষ্ঠা করেছে, তবুও প্রজাতির পার্থক্য এবং ঐতিহাসিক দ্বন্দ্ব এখনও দ্বন্দ্ব সৃষ্টি করতে পারে। রাষ্ট্র প্রজাতির দ্বন্দ্ব প্রতিরোধ এবং সমাধানের জন্য নিম্নলিখিত ব্যবস্থা স্থাপন করে:</p><ul><li><strong>প্রজাতির বিষয়ক বিভাগ</strong>: বিশেষভাবে সকল প্রজাতির সম্পর্ক সমন্বয় করা, প্রজাতির বিবাদ সমাধান করা, এবং প্রজাতির বিনিময় প্রচার করার জন্য দায়বদ্ধ।</li><li><strong>প্রজাতির মিলন কমিটি</strong>: সকল প্রজাতির প্রতিনিধি দ্বারা গঠিত, এবং প্রজাতির দ্বন্দ্ব মধ্যস্থতা করা এবং ঐতিহাসিক মিলন প্রচার করার জন্য দায়বদ্ধ।</li><li><strong>বিরোধী বৈষম্য আইন</strong>: প্রজাতির ভিত্তিতে বৈষম্যমূলক আচরণ নিষিদ্ধ, এবং প্রজাতির বৈষম্যমূলক আচরণের জন্য আইন অনুযায়ী শাস্তি।</li><li><strong>সাংস্কৃতিক বিনিময় পরিকল্পনা</strong>: নিয়মিতভাবে সকল প্রজাতির সাংস্কৃতিক বিনিময় কার্যক্রম আয়োজন করা, এবং পারস্পরিক বোঝাপড়া এবং সম্মান বৃদ্ধি করা।</li><li><strong>মিশ্রিত বসতি এলাকা</strong>: সকল প্রজাতির মিশ্রিত বসতিকে উৎসাহিত করা, প্রজাতির বিচ্ছিন্নতা ভাঙা, এবং দৈনন্দিন বিনিময় প্রচার করা।</li></ul><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>সকল প্রজাতি হল হেঙ্গুয়ানঝৌর সবচেয়ে মূল্যবান সম্পদ। জীবনের রূপের বৈচিত্র্য বিভাজনের মূল কারণ নয়, বরং সহজাত বিবর্তনের চালিকা শক্তি। অ্যাঙ্কার সিম্বায়োসিস সভ্যতা সকল প্রজাতির সমানতার নীতি প্রতিষ্ঠা করা, পাঁচটি বংশগত শ্রেণীর বিভাজন স্থাপন করা, সকল প্রজাতির সহজাত সহযোগিতা প্রচার করা, এবং প্রজাতির দ্বন্দ্ব প্রতিরোধ ও সমাধান করার মাধ্যমে, সকল প্রজাতিকে লুঠ এবং যুদ্ধের ইতিহাস থেকে মুক্ত করে, এবং সহযোগিতামূলকভাবে সহজাত বিবর্তনের নতুন যুগের দিকে এগিয়ে যায়।</p><h2 id="সম্পর্কিত-নথি" tabindex="-1">সম্পর্কিত নথি <a class="header-anchor" href="#সম্পর্কিত-নথি" aria-label="Permalink to &quot;সম্পর্কিত নথি&quot;">​</a></h2><ul><li>51-人族定位与特质 (মানব প্রজাতির অবস্থান এবং বৈশিষ্ট্য)</li><li>52-异族分类与共生 (বিদেশী প্রজাতির শ্রেণীবিভাগ এবং সহজাত)</li><li>05-万族共进基本纲领 (সকল প্রজাতির সহযোগিতামূলক অগ্রগতির মূল প্রোগ্রাম)</li><li>40-共生宪法总纲 (সিম্বায়োসিস সংবিধানের মূল নীতি)</li></ul>',30)])])}const c=a(i,[["render",n]]);export{b as __pageData,c as default};
